#[cfg_attr(trust_verify, trust::skip)]
pub fn presentation_gate_model() -> Model {
    // color' = if (wants_emoji' OR Buggy) then 1 else 0. TLA primed semantics use
    // unprimed vars on the RHS, so substitute the LITERAL value each action is
    // about to assign to `wants_emoji` (1 for WantEmoji, 0 for WantText).
    let color_for = |wants_emoji_next: i64| {
        if_(
            gt(add(int(wants_emoji_next), cst("Buggy")), int(0)),
            int(1),
            int(0),
        )
    };
    Model {
        name: "PresentationGate",
        consts: vec![("Buggy", 0)],
        vars: vec![
            StateVar {
                name: "wants_emoji",
                init: 0,
            },
            StateVar {
                name: "color",
                init: 0,
            },
        ],
        fn_vars: vec![],
        actions: vec![
            Action {
                // The code point has default-emoji presentation (or VS16): colour allowed.
                name: "WantEmoji",
                guard: Some(le(var("wants_emoji"), int(0))),
                updates: vec![
                    Update {
                        var: "wants_emoji",
                        expr: int(1),
                    },
                    Update {
                        var: "color",
                        expr: color_for(1),
                    },
                ],
            },
            Action {
                // A default-text code point: colour must be withheld (the fix).
                name: "WantText",
                guard: Some(gt(var("wants_emoji"), int(0))),
                updates: vec![
                    Update {
                        var: "wants_emoji",
                        expr: int(0),
                    },
                    Update {
                        var: "color",
                        expr: color_for(0),
                    },
                ],
            },
        ],
        invariants: vec![Invariant {
            // A colour resolution implies the code point wanted emoji presentation.
            name: "NoColorForText",
            expr: le(var("color"), var("wants_emoji")),
        }],
    }
}

/// METRICS FRESHNESS GATE (introspection G3) — the abstract twin of `aterm-gui`'s
/// [`MetricsSnapshot::staled`](../../aterm_gui/metrics_service): a poll-driven figure
/// presented as LIVE must never be older than the `Stale` TTL, so a stalled/parked
/// sampler decays to honest `n/a` rather than rendering its last value forever. The
/// real-code binding is aterm-gui's `staleness_gate_matches_freshness_model` (the
/// shipping gate driven in lockstep with this model, with a no-revert negative control).
///
/// Scalar projection `<<age, live>>`: `age` = ticks since the last fresh sample, `live`
/// = whether the figure is still reported as available. `Sample` resets to a fresh live
/// figure (`age = 0`, `live = 1`); `Tick` ages the figure one step (guarded `age <=
/// Stale`, so `age` is bounded at `Stale + 1`) and, IN THE SAME STEP, drops `live` to 0
/// exactly when the new age crosses `Stale` — an ATOMIC expiry (no transient live-and-
/// stale state). `Stale` is the TTL in ticks (5, matching `STALE = 5s`).
///
/// `Buggy = 0` (committed): `Tick` expires the figure, so `FreshWhenLive` holds — a
/// live figure is never staler than `Stale`. `Buggy = 1`: the gate FAILS to expire
/// (keeps `live = 1` past `Stale`), so `ty` reaches `live = 1 ∧ age > Stale` → a
/// counterexample. Thus `ty` PROVES the freshness invariant and CATCHES the no-revert
/// bug (a stalled sampler rendering a stale value as live).
// Skip (T2 vcgen-budget lane): a spec-model DATA constructor — nested
// `vec!`/struct literals whose aggregate-operand count exceeds the
// VC-generation work budget, so its obligations are left Unknown
// fail-closed regardless. No runtime logic and no panic surface beyond
// the idiomatic allocs; the MODEL it returns is what `ty` machine-checks.
#[cfg_attr(trust_verify, trust::skip)]
pub fn freshness_model() -> Model {
    // live' = if (age+1 > Stale) then (if Buggy then keep-live else expire) else live.
    // TLA primed semantics read the PRE-state, so `age + 1` is the value `age'` takes.
    let live_next = if_(
        gt(add(var("age"), int(1)), cst("Stale")),
        if_(eq(cst("Buggy"), int(1)), int(1), int(0)),
        int(1),
    );
    Model {
        name: "Freshness",
        consts: vec![("Stale", 5), ("Buggy", 0)],
        vars: vec![
            StateVar {
                name: "age",
                init: 0,
            },
            StateVar {
                name: "live",
                init: 1,
            },
        ],
        fn_vars: vec![],
        actions: vec![
            Action {
                // A fresh sample landed: reset the age and present it as live.
                name: "Sample",
                guard: None,
                updates: vec![
                    Update {
                        var: "age",
                        expr: int(0),
                    },
                    Update {
                        var: "live",
                        expr: int(1),
                    },
                ],
            },
            Action {
                // One tick older; the correct gate expires `live` as age crosses Stale.
                // Guard bounds age at Stale+1, keeping the state space finite.
                name: "Tick",
                guard: Some(le(var("age"), cst("Stale"))),
                updates: vec![
                    Update {
                        var: "age",
                        expr: add(var("age"), int(1)),
                    },
                    Update {
                        var: "live",
                        expr: live_next,
                    },
                ],
            },
        ],
        invariants: vec![Invariant {
            // A figure reported as live is never staler than the TTL.
            name: "FreshWhenLive",
            expr: or_(eq(var("live"), int(0)), le(var("age"), cst("Stale"))),
        }],
    }
}

/// NETWORK-HEALTH HONESTY LATTICE (introspection G3) — the abstract twin of `aterm-gui`'s
/// [`net_health_classify`](../../aterm_gui/sysmetrics): the coarse Online/Slow/Offline/
/// Unknown classifier must never claim a state it cannot prove. The real-code binding is
/// aterm-gui's `net_health_matches_model` (the shipping classifier enumerated over its
/// whole finite input domain, with a `Buggy`-flip control mislabelling an unreachable
/// link as Online).
///
/// Scalar projection `<<reach, health>>`: `reach` = 1 iff there is a POSITIVE
/// reachability proof (a live default route, not merely a present link), `health` = the
/// classifier output (`0` Unknown, `1` Offline, `2` Slow, `3` Online). Each `Probe*`
/// action sets both atomically for one probe outcome, spreading the input space:
/// reachable-fast → Online, reachable-degraded → Slow, unreachable → Offline (or, under
/// `Buggy`, a dishonest Online), probe-undecided → Unknown.
///
/// `Buggy = 0` (committed): `Online`/`Slow` are set ONLY with `reach = 1`, and `Offline`
/// only with `reach = 0`, so both honesty invariants hold. `Buggy = 1`: the unreachable
/// probe reports `Online` with `reach = 0`, so `ty` reaches `health = Online ∧ reach = 0`
/// → a counterexample. Thus `ty` PROVES the honesty lattice and CATCHES a classifier
/// that fabricates reachability.
// Skip (T2 vcgen-budget lane): a spec-model DATA constructor — nested
// `vec!`/struct literals whose aggregate-operand count exceeds the
// VC-generation work budget, so its obligations are left Unknown
// fail-closed regardless. No runtime logic and no panic surface beyond
// the idiomatic allocs; the MODEL it returns is what `ty` machine-checks.
#[cfg_attr(trust_verify, trust::skip)]
pub fn net_health_model() -> Model {
    Model {
        name: "NetHealth",
        consts: vec![("Buggy", 0)],
        vars: vec![
            StateVar {
                name: "reach",
                init: 0,
            },
            StateVar {
                name: "health",
                init: 0,
            },
        ],
        fn_vars: vec![],
        actions: vec![
            Action {
                // Positive reachable proof, fast link → Online.
                name: "ProbeOnline",
                guard: None,
                updates: vec![
                    Update {
                        var: "reach",
                        expr: int(1),
                    },
                    Update {
                        var: "health",
                        expr: int(3),
                    },
                ],
            },
            Action {
                // Positive reachable proof, transient/slow link → Slow.
                name: "ProbeSlow",
                guard: None,
                updates: vec![
                    Update {
                        var: "reach",
                        expr: int(1),
                    },
                    Update {
                        var: "health",
                        expr: int(2),
                    },
                ],
            },
            Action {
                // No reachable proof → Offline. Buggy=1 dishonestly reports Online.
                name: "ProbeOffline",
                guard: None,
                updates: vec![
                    Update {
                        var: "reach",
                        expr: int(0),
                    },
                    Update {
                        var: "health",
                        expr: if_(eq(cst("Buggy"), int(1)), int(3), int(1)),
                    },
                ],
            },
            Action {
                // The probe couldn't decide → Unknown (never a fabricated state).
                name: "ProbeUnknown",
                guard: None,
                updates: vec![
                    Update {
                        var: "reach",
                        expr: int(0),
                    },
                    Update {
                        var: "health",
                        expr: int(0),
                    },
                ],
            },
        ],
        invariants: vec![
            Invariant {
                // Online is claimed only with a positive reachability proof.
                name: "HonestOnline",
                expr: or_(neq(var("health"), int(3)), eq(var("reach"), int(1))),
            },
            Invariant {
                // Offline is claimed only without a reachability proof.
                name: "HonestOffline",
                expr: or_(neq(var("health"), int(1)), eq(var("reach"), int(0))),
            },
        ],
    }
}

/// LIGATURE SLICING GATE (M4) — the conservative shaping-acceptance policy that
/// admits EXACTLY the two grid-mappable shape forms and rejects everything else.
/// The real decision is aterm-render's pure
/// [`aterm_render::ligature_shaping::classify_shape`] (the shaping seam in
/// `shape_ligature_run`); the Tier-1 binding is aterm-render's
/// `tests/ligature_slice.rs::classify_shape_lattice` (the SAME conservativeness
/// invariant, enumerated over the small-count lattice) and the `gate_*` kani
/// proofs.
///
/// The abstraction: a shape has `n_in` input cells and `n_out` output glyphs, and
/// a config flag `admit` (Cascadia N:1 admission, default OFF). The gate ACCEPTS
/// iff the shape is grid-mappable — either 1:1 (`n_out == n_in`, the shipping
/// Fira/JetBrains spacer form) or, WHEN `admit`, an N:1 collapse (`n_out == 1`,
/// `n_in >= 2`, the Cascadia form). `ty` PROVES `ConservativeAccept` at `Buggy=0`
/// (`accept` never exceeds the grid-mappable envelope — no non-mappable shape ever
/// reaches the blitter) over the whole bounded `(n_in, n_out, admit)` space, and
/// CATCHES the defect at `Buggy=1` (a gate that admits a collapse WITHOUT the
/// flag — dropping the `admit` guard — which draws a wide glyph the slicing path
/// is not wired for) -> counterexample. The N:1 tile arithmetic (slice at `cell_w`
/// boundaries) is NOT here — ty has no multiplication — it is the L0 lattice proof
/// in `tests/ligature_slice.rs` (the M4 rounding/scaling waiver).
#[must_use]
// Skip (T2 vcgen-budget lane): a spec-model DATA constructor — nested
// `vec!`/struct literals whose aggregate-operand count exceeds the
// VC-generation work budget, so its obligations are left Unknown
// fail-closed regardless. No runtime logic and no panic surface beyond
// the idiomatic allocs; the MODEL it returns is what `ty` machine-checks.
#[cfg_attr(trust_verify, trust::skip)]
pub fn ligature_gate_model() -> Model {
    // Cap on n_in / n_out — enough to reach 1:1, N:1 collapse (N up to 4), partial
    // collapse (3:2), and expansion (2:3).
    let n = 4;
    // The two grid-mappable predicates over the UNPRIMED (picked) counts.
    let one_to_one = || and_(gt(var("n_in"), int(0)), eq(var("n_out"), var("n_in")));
    let collapse = || and_(eq(var("n_out"), int(1)), gt(var("n_in"), int(1)));
    // accept' = 1:1 ? 1 : (collapse AND (admit OR Buggy)) ? 1 : 0. Buggy weakens the
    // `admit` guard, reproducing the "admit collapse without the flag" defect.
    let admit_or_buggy = gt(add(var("admit"), cst("Buggy")), int(0));
    let accept_expr = if_(
        one_to_one(),
        int(1),
        if_(and_(collapse(), admit_or_buggy), int(1), int(0)),
    );
    Model {
        name: "LigatureGate",
        consts: vec![("Buggy", 0)],
        vars: vec![
            StateVar {
                name: "phase",
                init: 0,
            },
            StateVar {
                name: "n_in",
                init: 0,
            },
            StateVar {
                name: "n_out",
                init: 0,
            },
            StateVar {
                name: "admit",
                init: 0,
            },
            StateVar {
                name: "accept",
                init: 0,
            },
        ],
        fn_vars: vec![],
        actions: vec![
            Action {
                // Pick a shape: any (n_in, n_out) in 0..=N and any flag setting.
                name: "Pick",
                guard: Some(eq(var("phase"), int(0))),
                updates: vec![
                    Update {
                        var: "n_in",
                        expr: in_range(int(0), int(n)),
                    },
                    Update {
                        var: "n_out",
                        expr: in_range(int(0), int(n)),
                    },
                    Update {
                        var: "admit",
                        expr: in_range(int(0), int(1)),
                    },
                    Update {
                        var: "accept",
                        expr: int(0),
                    },
                    Update {
                        var: "phase",
                        expr: int(1),
                    },
                ],
            },
            Action {
                // Classify the picked shape (classify_shape); loop back so the state
                // space is the whole picked lattice with no deadlock.
                name: "Classify",
                guard: Some(eq(var("phase"), int(1))),
                updates: vec![
                    Update {
                        var: "accept",
                        expr: accept_expr,
                    },
                    Update {
                        var: "phase",
                        expr: int(0),
                    },
                ],
            },
        ],
        invariants: vec![Invariant {
            // CONSERVATIVENESS: an accepted shape is ALWAYS grid-mappable — 1:1, or
            // an N:1 collapse WITH the flag. `accept <= grid_mappable`. Note the
            // envelope uses the TRUE `admit`, so a Buggy accept of an unflagged
            // collapse breaks it.
            name: "ConservativeAccept",
            expr: le(
                var("accept"),
                if_(
                    or_(one_to_one(), and_(collapse(), eq(var("admit"), int(1)))),
                    int(1),
                    int(0),
                ),
            ),
        }],
    }
}

/// HDR PRESENT GATE (M3 phase B) — the EDR ("HDR glow") present policy: when is
/// the swapchain `Rgba16Float`, when does the blit linear-decode, when does
/// the >1.0 aurora pass run. The real decisions are aterm-gpu's pure
/// `format_plan::hdr_swapchain_wants_f16` (the Attach seam,
/// `GpuRenderer::create_window_surface`) and `format_plan::hdr_present_plan`
/// (the Present seam, `present_input`); the Tier-1 binding is aterm-gpu's
/// `tests/hdr_gate.rs` exhaustive 2^3 enumeration of BOTH shipping functions
/// chained Attach→Present, asserting THESE invariants (a complete proof — the
/// domain is finite booleans). The float clamp laws the gate FEEDS (grid ≤ 1.0,
/// additive ≤ EDR headroom) are proven separately in `aterm_render::hdr`
/// (exhaustive sweeps + trust-mc harnesses) — ty carries the boolean policy,
/// per the derive-layer division of labour.
///
/// Scalar projection `<<hdr_glow, supports_f16, glow, attached, is_f16,
/// blit_hdr, boost>>`: `Observe` spreads the three input facts
/// nondeterministically (config opt-in, surface capability, aurora presence)
/// and resets the window lifecycle; `Attach` picks the swapchain format ONCE
/// (`is_f16' = hdr_glow ∧ supports_f16`); `Present` (repeatable) derives the
/// blit decode from the ACTUAL format (`blit_hdr' = is_f16` — the encode
/// follows the surface, so live config flips degrade safely) and the aurora
/// pass from all three (`boost' = hdr_glow ∧ is_f16 ∧ glow`).
///
/// `Buggy` gates the DEFECT CLASS the gate exists to exclude: with `Buggy = 1`
/// Attach picks f16 whenever the surface supports it — ignoring the config —
/// so an untouched default install lands on an EDR swapchain and
/// `SdrInvariance` (hdr_glow off ⇒ nothing HDR ever happens) is violated. Thus
/// `ty` PROVES the invariance (Buggy=0) and CATCHES the regression (Buggy=1 →
/// counterexample).
// Skip (T2 vcgen-budget lane): a spec-model DATA constructor — nested
// `vec!`/struct literals whose aggregate-operand count exceeds the
// VC-generation work budget, so its obligations are left Unknown
// fail-closed regardless. No runtime logic and no panic surface beyond
// the idiomatic allocs; the MODEL it returns is what `ty` machine-checks.
#[cfg_attr(trust_verify, trust::skip)]
pub fn hdr_present_gate_model() -> Model {
    // is_f16' at Attach: the shipping policy (hdr_glow AND supports_f16), or the
    // Buggy=1 defect (supports_f16 alone — config ignored).
    let attach_pick = if_(
        gt(cst("Buggy"), int(0)),
        var("supports_f16"),
        if_(
            and_(gt(var("hdr_glow"), int(0)), gt(var("supports_f16"), int(0))),
            int(1),
            int(0),
        ),
    );
    Model {
        name: "HdrPresentGate",
        consts: vec![("Buggy", 0)],
        vars: vec![
            StateVar {
                name: "hdr_glow",
                init: 0,
            },
            StateVar {
                name: "supports_f16",
                init: 0,
            },
            StateVar {
                name: "glow",
                init: 0,
            },
            StateVar {
                name: "attached",
                init: 0,
            },
            StateVar {
                name: "is_f16",
                init: 0,
            },
            StateVar {
                name: "blit_hdr",
                init: 0,
            },
            StateVar {
                name: "boost",
                init: 0,
            },
        ],
        fn_vars: vec![],
        actions: vec![
            Action {
                // A window lifecycle begins: observe the config opt-in, the
                // surface's f16 capability, and whether aurora quads exist this
                // session (all 2^3 combinations); reset the derived state.
                name: "Observe",
                guard: None,
                updates: vec![
                    Update {
                        var: "hdr_glow",
                        expr: in_range(int(0), int(1)),
                    },
                    Update {
                        var: "supports_f16",
                        expr: in_range(int(0), int(1)),
                    },
                    Update {
                        var: "glow",
                        expr: in_range(int(0), int(1)),
                    },
                    Update {
                        var: "attached",
                        expr: int(0),
                    },
                    Update {
                        var: "is_f16",
                        expr: int(0),
                    },
                    Update {
                        var: "blit_hdr",
                        expr: int(0),
                    },
                    Update {
                        var: "boost",
                        expr: int(0),
                    },
                ],
            },
            Action {
                // Surface attach: pick the swapchain format once
                // (format_plan::hdr_swapchain_wants_f16).
                name: "Attach",
                guard: Some(le(var("attached"), int(0))),
                updates: vec![
                    Update {
                        var: "attached",
                        expr: int(1),
                    },
                    Update {
                        var: "is_f16",
                        expr: attach_pick,
                    },
                ],
            },
            Action {
                // A present on the attached surface
                // (format_plan::hdr_present_plan): the blit decode follows the
                // ACTUAL format; the aurora pass needs config AND format AND glow.
                name: "Present",
                guard: Some(gt(var("attached"), int(0))),
                updates: vec![
                    Update {
                        var: "blit_hdr",
                        expr: var("is_f16"),
                    },
                    Update {
                        var: "boost",
                        expr: if_(
                            and_(
                                gt(var("hdr_glow"), int(0)),
                                and_(gt(var("is_f16"), int(0)), gt(var("glow"), int(0))),
                            ),
                            int(1),
                            int(0),
                        ),
                    },
                ],
            },
        ],
        invariants: vec![
            Invariant {
                // SDR INVARIANCE (the M3 phase-B contract): hdr_glow off ⇒ no
                // f16 swapchain, no linear decode, no >1.0 aurora pass — the
                // present is byte-identical to pre-M3. hdr_glow = 0 =>
                // is_f16 = 0 /\ blit_hdr = 0 /\ boost = 0.
                name: "SdrInvariance",
                expr: or_(
                    gt(var("hdr_glow"), int(0)),
                    and_(
                        eq(var("is_f16"), int(0)),
                        and_(eq(var("blit_hdr"), int(0)), eq(var("boost"), int(0))),
                    ),
                ),
            },
            Invariant {
                // A >1.0 emission can only land on a float swapchain whose blit
                // decoded to linear: boost <= blit_hdr (and blit_hdr <= is_f16).
                name: "BoostNeedsLinearF16",
                expr: and_(
                    le(var("boost"), var("blit_hdr")),
                    le(var("blit_hdr"), var("is_f16")),
                ),
            },
            Invariant {
                // The EDR format is never picked without surface support —
                // holds even under Buggy=1 (whose violation is config, not caps).
                name: "F16NeedsSupport",
                expr: le(var("is_f16"), var("supports_f16")),
            },
        ],
    }
}

/// CHROME FACE GATE — chrome typography to grid standard: which face draws a
/// chrome (tray/overlay) glyph. The real decision is aterm-gui's pure
