// Skip (T2 vcgen-budget lane): a spec-model DATA constructor — nested
// `vec!`/struct literals whose aggregate-operand count exceeds the
// VC-generation work budget, so its obligations are left Unknown
// fail-closed regardless. No runtime logic and no panic surface beyond
// the idiomatic allocs; the MODEL it returns is what `ty` machine-checks.
#[cfg_attr(trust_verify, trust::skip)]
pub fn vibrancy_contrast_model() -> Model {
    // max(base, Floor): the auto-engaged legibility floor for translucent glass.
    let maxf = || if_(gt(var("base"), cst("Floor")), var("base"), cst("Floor"));
    // The effective floor from the SETTLED (unprimed) scene: translucent windows
    // floor up to WCAG AA; opaque windows keep the user's configured value.
    // Buggy=1 drops the auto-floor (returns raw base even while translucent).
    let effective = if_(
        eq(var("translucent"), int(1)),
        if_(eq(cst("Buggy"), int(0)), maxf(), var("base")),
        var("base"),
    );
    Model {
        name: "VibrancyContrast",
        consts: vec![("Buggy", 0), ("Floor", 3)],
        vars: vec![
            StateVar {
                name: "phase",
                init: 0,
            },
            StateVar {
                name: "translucent",
                init: 0,
            },
            StateVar {
                name: "base",
                init: 0,
            },
            StateVar {
                name: "effective",
                init: 0,
            },
        ],
        fn_vars: vec![],
        actions: vec![
            Action {
                name: "Pick",
                guard: Some(le(var("phase"), int(0))),
                updates: vec![
                    Update {
                        var: "translucent",
                        expr: in_range(int(0), int(1)),
                    },
                    Update {
                        var: "base",
                        expr: in_range(int(0), int(6)),
                    },
                    Update {
                        var: "effective",
                        expr: int(0),
                    },
                    Update {
                        var: "phase",
                        expr: int(1),
                    },
                ],
            },
            Action {
                name: "Fire",
                guard: Some(gt(var("phase"), int(0))),
                updates: vec![
                    Update {
                        var: "effective",
                        expr: effective,
                    },
                    Update {
                        var: "phase",
                        expr: int(0),
                    },
                ],
            },
        ],
        invariants: vec![Invariant {
            // Picked-but-unfired states (phase = 1) carry a stale effective and
            // are exempt; every settled translucent scene clears the floor.
            name: "NeverIllegible",
            expr: or_(
                gt(var("phase"), int(0)),
                or_(
                    eq(var("translucent"), int(0)),
                    le(cst("Floor"), var("effective")),
                ),
            ),
        }],
    }
}

/// W1 COMPOSITOR-STRETCH FIX — the abstract twin of the window-fit + padding-
/// absorption policy `aterm_render::pad_split` (the real code seam; Tier-1 lives
/// in `aterm-render/tests/pad_absorption.rs`, which drives THIS model's own
/// interpreter against the shipping function point-for-point over the model's
/// whole lattice, plus a lattice-exhaustive direct check).
///
/// The law: the swapchain is sized to the RAW window pixels; the maximal grid
/// (`cols = floor((w - 2*pad)/cell)`) plus per-edge pads that absorb the
/// `0..cell-1` remainder must tile the window EXACTLY (`pad_lo + cols*cell +
/// pad_hi == w`), keep the configured pad floor, and split the remainder
/// near-evenly (`pad_lo <= pad_hi <= pad_lo + 1`) — so the compositor never
/// rescales the frame and the bands never lean visibly to one side.
///
/// The `ty` expression language has no `*`/`/`, so the model builds `cols*cell`
/// by REPEATED ADDITION (`FitColumn` accumulates `acc += cell` while it fits;
/// maximality is the `Settle` guard) and computes `rem/2` by a bounded case
/// split (`rem <= 3` on this lattice). The full-bit-width arithmetic twin lives
/// in `aterm-render`'s `pad_split_kani` trust-mc harnesses.
///
/// `Buggy` gates the defect class the near-even law exists to forbid: with
/// `Buggy = 1` the WHOLE remainder lands on the trailing edge (`pad_lo` keeps
/// none of it), so a `rem >= 2` window violates `NearEvenSplit` — `ty` PROVES
/// the split (Buggy=0) and CATCHES the lopsided variant (Buggy=1).
// Skip (T2 vcgen-budget lane): a spec-model DATA constructor — nested
// `vec!`/struct literals whose aggregate-operand count exceeds the
// VC-generation work budget, so its obligations are left Unknown
// fail-closed regardless. No runtime logic and no panic surface beyond
// the idiomatic allocs; the MODEL it returns is what `ty` machine-checks.
#[cfg_attr(trust_verify, trust::skip)]
pub fn pad_absorption_model() -> Model {
    // usable == w - 2*pad; rem == usable - acc. All unprimed (evaluated at the
    // pre-state of the one Settle step that consumes them).
    let usable = || sub(sub(var("w"), var("pad")), var("pad"));
    let rem = || sub(usable(), var("acc"));
    // rem/2 without division: 0 for rem in {0,1}, 1 for {2,3} (cell <= 4 on
    // this lattice, so rem <= 3).
    let half = || if_(le(rem(), int(1)), int(0), int(1));
    // Buggy=1: the lopsided split — the leading pad keeps none of the remainder.
    let lo_share = || if_(gt(cst("Buggy"), int(0)), int(0), half());
    // Invariants hold vacuously until the split settles (phase 4).
    let settled_implies = |body: Expr| or_(neq(var("phase"), int(4)), body);
    Model {
        name: "PadAbsorption",
        consts: vec![("Buggy", 0)],
        vars: vec![
            StateVar {
                name: "phase",
                init: 0,
            },
            StateVar {
                name: "cell",
                init: 1,
            },
            StateVar {
                name: "pad",
                init: 0,
            },
            StateVar { name: "w", init: 0 },
            StateVar {
                name: "acc",
                init: 0,
            },
            StateVar {
                name: "pad_lo",
                init: 0,
            },
            StateVar {
                name: "pad_hi",
                init: 0,
            },
        ],
        fn_vars: vec![],
        actions: vec![
            Action {
                name: "PickCell",
                guard: Some(eq(var("phase"), int(0))),
                updates: vec![
                    Update {
                        var: "cell",
                        expr: in_range(int(1), int(4)),
                    },
                    Update {
                        var: "phase",
                        expr: int(1),
                    },
                ],
            },
            Action {
                name: "PickPad",
                guard: Some(eq(var("phase"), int(1))),
                updates: vec![
                    Update {
                        var: "pad",
                        expr: in_range(int(0), int(2)),
                    },
                    Update {
                        var: "phase",
                        expr: int(2),
                    },
                ],
            },
            Action {
                // EVERY in-domain window on the lattice: w >= 2*pad + cell (at
                // least one padded cell fits), up to the exhaustive cap.
                name: "PickWin",
                guard: Some(eq(var("phase"), int(2))),
                updates: vec![
                    Update {
                        var: "w",
                        expr: in_range(add(add(var("pad"), var("pad")), var("cell")), int(14)),
                    },
                    Update {
                        var: "phase",
                        expr: int(3),
                    },
                ],
            },
            Action {
                // cols*cell by repeated addition: fit one more column while it fits.
                name: "FitColumn",
                guard: Some(and_(
                    eq(var("phase"), int(3)),
                    le(add(var("acc"), var("cell")), usable()),
                )),
                updates: vec![Update {
                    var: "acc",
                    expr: add(var("acc"), var("cell")),
                }],
            },
            Action {
                // Maximality IS the guard: one more column would overflow the
                // usable extent. Absorb the remainder into the two pads.
                name: "Settle",
                guard: Some(and_(
                    eq(var("phase"), int(3)),
                    gt(add(var("acc"), var("cell")), usable()),
                )),
                updates: vec![
                    Update {
                        var: "pad_lo",
                        expr: add(var("pad"), lo_share()),
                    },
                    Update {
                        var: "pad_hi",
                        expr: add(var("pad"), sub(rem(), lo_share())),
                    },
                    Update {
                        var: "phase",
                        expr: int(4),
                    },
                ],
            },
        ],
        invariants: vec![
            Invariant {
                // pad_lo + cols*cell + pad_hi == w: no pixel scaled or dropped.
                name: "ExactCover",
                expr: settled_implies(eq(
                    add(add(var("pad_lo"), var("acc")), var("pad_hi")),
                    var("w"),
                )),
            },
            Invariant {
                // Both pads keep the configured floor.
                name: "PadsFloor",
                expr: settled_implies(and_(
                    le(var("pad"), var("pad_lo")),
                    le(var("pad"), var("pad_hi")),
                )),
            },
            Invariant {
                // |pad_hi - pad_lo| <= 1, leaning to the trailing edge.
                name: "NearEvenSplit",
                expr: settled_implies(and_(
                    le(var("pad_lo"), var("pad_hi")),
                    le(var("pad_hi"), add(var("pad_lo"), int(1))),
                )),
            },
            Invariant {
                // The settled grid is maximal (restated as a state property).
                name: "Maximal",
                expr: settled_implies(gt(
                    add(var("acc"), var("cell")),
                    sub(sub(var("w"), var("pad")), var("pad")),
                )),
            },
        ],
    }
}

/// RAW-renderer asymmetric top-padding redistribution and cache identity.
///
/// This model deliberately describes the renderer's LEGACY RAW TRANSPORT
/// allocation, before a frontend crop: tightening only the raw top edge does
/// not change that allocation, so its raw bottom absorbs `pad - pad_top` and
/// `pad_top + raw_pad_bottom == 2*pad`. [`visible_pad_crop_model`] separately
/// proves the GUI-visible contract (`visible_bottom == pad`). The requested top
/// is clamped to the base pad. Because raw dimensions and terminal content can
/// remain byte-identical while the grid Y origin moves, CPU/GPU cache reuse must
/// key the effective `grid_top`, not dimensions alone.
///
/// The bounded lattice abstracts grid height away (it cancels from the exact
/// cover equation) but retains the independent head band in `grid_top`. `Buggy=1`
/// reproduces both defect classes: it accepts an unclamped top while leaving the
/// bottom at the old symmetric pad, and it reuses a valid cache solely because
/// dimensions/content match even when the cached grid origin differs.
#[must_use]
#[cfg_attr(trust_verify, trust::skip)]
pub fn asymmetric_pad_layout_model() -> Model {
    let clamp_initial = || {
        if_(
            le(var("initial_request"), var("pad")),
            var("initial_request"),
            var("pad"),
        )
    };
    let clamp_changed = || {
        if_(
            le(var("changed_request"), var("pad")),
            var("changed_request"),
            var("pad"),
        )
    };
    let initial_top = || {
        if_(
            eq(cst("Buggy"), int(1)),
            var("initial_request"),
            clamp_initial(),
        )
    };
    let changed_top = || {
        if_(
            eq(cst("Buggy"), int(1)),
            var("changed_request"),
            clamp_changed(),
        )
    };
    let initial_bottom = || {
        if_(
            eq(cst("Buggy"), int(1)),
            var("pad"),
            sub(add(var("pad"), var("pad")), clamp_initial()),
        )
    };
    let changed_bottom = || {
        if_(
            eq(cst("Buggy"), int(1)),
            var("pad"),
            sub(add(var("pad"), var("pad")), clamp_changed()),
        )
    };
    let layouts_match = || eq(var("cached_grid_top"), var("grid_top"));
    let settled_layout = || gt(var("phase"), int(1));
    Model {
        name: "AsymmetricPadLayout",
        consts: vec![("Buggy", 0)],
        vars: vec![
            StateVar {
                name: "phase",
                init: 0,
            },
            StateVar {
                name: "pad",
                init: 1,
            },
            StateVar {
                name: "head",
                init: 0,
            },
            StateVar {
                name: "initial_request",
                init: 0,
            },
            StateVar {
                name: "changed_request",
                init: 0,
            },
            StateVar {
                name: "pad_top",
                init: 0,
            },
            StateVar {
                name: "pad_bottom",
                init: 0,
            },
            StateVar {
                name: "grid_top",
                init: 0,
            },
            StateVar {
                name: "cached_grid_top",
                init: 0,
            },
            StateVar {
                name: "cache_valid",
                init: 0,
            },
            StateVar {
                name: "cache_hit",
                init: 0,
            },
            StateVar {
                name: "full_repaint",
                init: 0,
            },
        ],
        fn_vars: vec![],
        actions: vec![
            Action {
                name: "PickLayout",
                guard: Some(eq(var("phase"), int(0))),
                updates: vec![
                    Update {
                        var: "pad",
                        expr: in_range(int(1), int(3)),
                    },
                    Update {
                        var: "head",
                        expr: in_range(int(0), int(2)),
                    },
                    Update {
                        var: "initial_request",
                        expr: in_range(int(0), int(4)),
                    },
                    Update {
                        var: "changed_request",
                        expr: in_range(int(0), int(4)),
                    },
                    Update {
                        var: "phase",
                        expr: int(1),
                    },
                ],
            },
            Action {
                name: "ApplyInitialTop",
                guard: Some(eq(var("phase"), int(1))),
                updates: vec![
                    Update {
                        var: "pad_top",
                        expr: initial_top(),
                    },
                    Update {
                        var: "pad_bottom",
                        expr: initial_bottom(),
                    },
                    Update {
                        var: "grid_top",
                        expr: add(var("head"), initial_top()),
                    },
                    Update {
                        var: "phase",
                        expr: int(2),
                    },
                ],
            },
            Action {
                name: "PrimeLayoutCache",
                guard: Some(eq(var("phase"), int(2))),
                updates: vec![
                    Update {
                        var: "cached_grid_top",
                        expr: var("grid_top"),
                    },
                    Update {
                        var: "cache_valid",
                        expr: int(1),
                    },
                    Update {
                        var: "cache_hit",
                        expr: int(0),
                    },
                    Update {
                        var: "full_repaint",
                        expr: int(0),
                    },
                    Update {
                        var: "phase",
                        expr: int(3),
                    },
                ],
            },
            Action {
                name: "ApplyChangedTop",
                guard: Some(eq(var("phase"), int(3))),
                updates: vec![
                    Update {
                        var: "pad_top",
                        expr: changed_top(),
                    },
                    Update {
                        var: "pad_bottom",
                        expr: changed_bottom(),
                    },
                    Update {
                        var: "grid_top",
                        expr: add(var("head"), changed_top()),
                    },
                    Update {
                        var: "phase",
                        expr: int(4),
                    },
                ],
            },
            Action {
                name: "RenderWithLayoutCache",
                guard: Some(and_(
                    eq(var("phase"), int(4)),
                    eq(var("cache_valid"), int(1)),
                )),
                updates: vec![
                    Update {
                        var: "cache_hit",
                        expr: if_(
                            eq(cst("Buggy"), int(1)),
                            int(1),
                            if_(layouts_match(), int(1), int(0)),
                        ),
                    },
                    Update {
                        var: "full_repaint",
                        expr: if_(
                            eq(cst("Buggy"), int(1)),
                            int(0),
                            if_(layouts_match(), int(0), int(1)),
                        ),
                    },
                    Update {
                        var: "phase",
                        expr: int(5),
                    },
                ],
            },
        ],
        invariants: vec![
            Invariant {
                name: "ExactVerticalPadCover",
                expr: if_(
                    settled_layout(),
                    eq(
                        add(var("pad_top"), var("pad_bottom")),
                        add(var("pad"), var("pad")),
                    ),
                    le(
                        add(var("pad_top"), var("pad_bottom")),
                        add(var("pad"), var("pad")),
                    ),
                ),
            },
            Invariant {
                name: "TopPadIsBounded",
                expr: if_(
                    settled_layout(),
                    le(var("pad_top"), var("pad")),
                    eq(var("pad_top"), int(0)),
                ),
            },
            Invariant {
                name: "BottomAbsorbsFreedPixels",
                expr: if_(
                    settled_layout(),
                    and_(
                        le(var("pad"), var("pad_bottom")),
                        le(var("pad_bottom"), add(var("pad"), var("pad"))),
                    ),
                    eq(var("pad_bottom"), int(0)),
                ),
            },
            Invariant {
                name: "GridOriginTracksTopAndHead",
                expr: if_(
                    settled_layout(),
                    eq(var("grid_top"), add(var("head"), var("pad_top"))),
                    eq(var("grid_top"), int(0)),
                ),
            },
            Invariant {
                name: "LayoutChangeForcesFullRepaint",
                expr: if_(
                    and_(
                        eq(var("phase"), int(5)),
                        neq(var("cached_grid_top"), var("grid_top")),
                    ),
                    and_(
                        eq(var("cache_hit"), int(0)),
                        eq(var("full_repaint"), int(1)),
                    ),
                    le(var("cache_hit"), int(1)),
                ),
            },
            Invariant {
                name: "IdenticalLayoutMayReuseCache",
                expr: if_(
                    and_(eq(var("phase"), int(5)), layouts_match()),
                    and_(
                        eq(var("cache_hit"), int(1)),
                        eq(var("full_repaint"), int(0)),
                    ),
                    le(var("full_repaint"), int(1)),
                ),
            },
            Invariant {
                name: "CacheDecisionIsTotal",
                expr: if_(
                    eq(var("phase"), int(5)),
                    eq(add(var("cache_hit"), var("full_repaint")), int(1)),
                    eq(add(var("cache_hit"), var("full_repaint")), int(0)),
                ),
            },
        ],
    }
}

/// GUI-visible crop from the renderer's conserved raw padding allocation.
///
/// The raw renderer remains `grid + head + 2*pad`, with a tightened top and an
/// expanded raw bottom. The GUI removes exactly `pad - pad_top` source rows, so
/// its exposed frame is `grid + head + pad_top + pad`: the requested/clamped top
/// is preserved and the visible bottom is ALWAYS the base pad. `Buggy=1`
/// reproduces the shipped defect by exposing the uncropped raw frame/bottom.
#[must_use]
#[cfg_attr(trust_verify, trust::skip)]
pub fn visible_pad_crop_model() -> Model {
    let resolved_top = || if_(le(var("request"), var("pad")), var("request"), var("pad"));
    let raw_height = || add(add(var("grid"), var("head")), add(var("pad"), var("pad")));
    let visible_height = || {
        add(
            add(var("grid"), var("head")),
            add(resolved_top(), var("pad")),
        )
    };
    let settled = || eq(var("phase"), int(2));
    Model {
        name: "VisiblePadCrop",
        consts: vec![("Buggy", 0)],
        vars: vec![
            StateVar {
                name: "phase",
                init: 0,
            },
            StateVar {
                name: "pad",
                init: 0,
            },
            StateVar {
                name: "request",
                init: 0,
            },
            StateVar {
                name: "grid",
                init: 1,
            },
            StateVar {
                name: "head",
                init: 0,
            },
            StateVar {
                name: "pad_top",
                init: 0,
            },
            StateVar {
                name: "raw_pad_bottom",
                init: 0,
            },
            StateVar {
                name: "raw_height",
                init: 0,
            },
            StateVar {
                name: "visible_pad_top",
                init: 0,
            },
            StateVar {
                name: "visible_pad_bottom",
                init: 0,
            },
            StateVar {
                name: "visible_height",
                init: 0,
            },
            StateVar {
                name: "crop_total",
                init: 0,
            },
        ],
        fn_vars: vec![],
        actions: vec![
            Action {
                name: "ChooseGeometry",
                guard: Some(eq(var("phase"), int(0))),
                updates: vec![
                    Update {
                        var: "pad",
                        expr: in_range(int(0), int(3)),
                    },
                    Update {
                        var: "request",
                        expr: in_range(int(0), int(4)),
                    },
                    Update {
                        var: "grid",
                        expr: in_range(int(1), int(4)),
                    },
                    Update {
                        var: "head",
                        expr: in_range(int(0), int(2)),
                    },
                    Update {
                        var: "phase",
                        expr: int(1),
                    },
                ],
            },
            Action {
                name: "Crop",
                guard: Some(eq(var("phase"), int(1))),
                updates: vec![
                    Update {
                        var: "pad_top",
                        expr: resolved_top(),
                    },
                    Update {
                        var: "raw_pad_bottom",
                        expr: sub(add(var("pad"), var("pad")), resolved_top()),
                    },
                    Update {
                        var: "raw_height",
                        expr: raw_height(),
                    },
                    Update {
                        var: "visible_pad_top",
                        expr: resolved_top(),
                    },
                    Update {
                        var: "visible_pad_bottom",
                        expr: if_(
                            eq(cst("Buggy"), int(1)),
                            sub(add(var("pad"), var("pad")), resolved_top()),
                            var("pad"),
                        ),
                    },
                    Update {
                        var: "visible_height",
                        expr: if_(eq(cst("Buggy"), int(1)), raw_height(), visible_height()),
                    },
                    Update {
                        var: "crop_total",
                        expr: if_(
                            eq(cst("Buggy"), int(1)),
                            int(0),
                            sub(var("pad"), resolved_top()),
                        ),
                    },
                    Update {
                        var: "phase",
                        expr: int(2),
                    },
                ],
            },
        ],
        invariants: vec![
            Invariant {
                name: "TopIsClamped",
                expr: if_(
                    settled(),
                    and_(
                        le(var("pad_top"), var("pad")),
                        eq(var("visible_pad_top"), var("pad_top")),
                    ),
                    eq(var("pad_top"), int(0)),
                ),
            },
            Invariant {
                name: "RawTransportConservesTwoPads",
                expr: if_(
                    settled(),
                    and_(
                        eq(
                            add(var("pad_top"), var("raw_pad_bottom")),
                            add(var("pad"), var("pad")),
                        ),
                        eq(var("raw_height"), raw_height()),
                    ),
                    eq(var("raw_height"), int(0)),
                ),
            },
            Invariant {
                name: "VisibleBottomIsBasePad",
                expr: if_(
                    settled(),
                    eq(var("visible_pad_bottom"), var("pad")),
                    eq(var("visible_pad_bottom"), int(0)),
                ),
            },
            Invariant {
                name: "VisibleHeightUsesIndependentEdges",
                expr: if_(
                    settled(),
                    eq(var("visible_height"), visible_height()),
                    eq(var("visible_height"), int(0)),
                ),
            },
            Invariant {
                name: "CropDeletesOnlyRemovedTop",
                expr: if_(
                    settled(),
                    and_(
                        eq(var("crop_total"), sub(var("pad"), var("pad_top"))),
                        eq(
                            var("raw_height"),
                            add(var("visible_height"), var("crop_total")),
                        ),
                    ),
                    eq(var("crop_total"), int(0)),
                ),
            },
        ],
    }
}

/// W3 CT FRACTIONAL BEARING — the abstract twin of the CoreText sub-pixel
/// placement policy `aterm_render::ct_pen_and_bearing` (the real code seam is
/// `CtFont::rasterize`; Tier-1 lives in
/// `aterm-render/tests/ct_fractional_bearing.rs`, which sweeps the pure fn over
/// a dense dyadic lattice AND drives THIS model's own interpreter against it
/// point-for-point, plus the FFI binding test in aterm-render's lib tests).
///
/// The sin (audit sin 10): `CtFont::rasterize` pinned each ink box to an
/// integer bitmap origin (pen `= -b`) and reported `round(b)` bearings, so
/// every glyph sat up to 0.5px off its designed position per axis, error
/// varying glyph-to-glyph. The fix splits the padded ink-box origin `b` into
/// an integer bearing `floor(b)` plus a RETAINED in-bitmap phase
/// `b - floor(b) ∈ [0, 1)`.
///
/// `ty`'s Expr language has no `*`/`/`, so the model computes the floor
/// decomposition OPERATIONALLY, in eighth-px fixed point (SCALE = 8): after
/// `PickB` (any bearing `b ∈ [-24, 24]` eighths, i.e. ±3px) and `Latch`
/// (`rem = b`, `bearing = 0`), `StepDown`/`StepUp` move whole pixels (8 units)
/// between `rem` and `bearing` until `rem ∈ [0, 8)`, and `Report` publishes
/// the placement. Safety: `Decompose` — `bearing + rem == b` at every step
/// (integer bearing + retained phase IS the designed position, exactly) — and
/// `PhaseInUnit` — the reported phase sits in `[0, 1)`. `Buggy = 1` gates the
/// PRE-FIX placement into `Report` (bearing rounded to the nearest px, phase
/// pinned to 0): any `b` off the whole-px grid then violates `Decompose`, so
/// `ty` PROVES the law at `Buggy=0` and CATCHES the rounded-pin defect at
/// `Buggy=1` (counterexample).
// Skip (T2 vcgen-budget lane): a spec-model DATA constructor — nested
// `vec!`/struct literals whose aggregate-operand count exceeds the
// VC-generation work budget, so its obligations are left Unknown
// fail-closed regardless. No runtime logic and no panic surface beyond
// the idiomatic allocs; the MODEL it returns is what `ty` machine-checks.
#[cfg_attr(trust_verify, trust::skip)]
pub fn ct_frac_bearing_model() -> Model {
    // The pre-fix report: round-to-nearest px (+8 iff rem >= 4) with the phase
    // discarded; the committed report keeps both untouched.
    let rounded = || {
        if_(
            gt(var("rem"), int(3)),
            add(var("bearing"), int(8)),
            var("bearing"),
        )
    };
    let report_bearing = if_(gt(cst("Buggy"), int(0)), rounded(), var("bearing"));
    let report_rem = if_(gt(cst("Buggy"), int(0)), int(0), var("rem"));
    // rem in [0, 8): the whole-px moves are exhausted, phase is sub-px.
    let rem_in_unit = || and_(le(int(0), var("rem")), le(var("rem"), int(7)));
    Model {
        name: "CtFracBearing",
        consts: vec![("Buggy", 0)],
        vars: vec![
            StateVar {
                name: "phase",
                init: 0,
            },
            StateVar { name: "b", init: 0 },
            StateVar {
                name: "rem",
                init: 0,
            },
            StateVar {
                name: "bearing",
                init: 0,
            },
        ],
        fn_vars: vec![],
        actions: vec![
            Action {
                // EVERY designed bearing on the lattice, negatives included
                // (a left-side bearing can be negative).
                name: "PickB",
                guard: Some(eq(var("phase"), int(0))),
                updates: vec![
                    Update {
                        var: "b",
                        expr: in_range(int(-24), int(24)),
                    },
                    Update {
                        var: "phase",
                        expr: int(1),
                    },
                ],
            },
            Action {
                // Start the decomposition: the whole origin is still phase.
                name: "Latch",
                guard: Some(eq(var("phase"), int(1))),
                updates: vec![
                    Update {
                        var: "rem",
                        expr: var("b"),
                    },
                    Update {
                        var: "phase",
                        expr: int(2),
                    },
                ],
            },
            Action {
                // Move one whole px of positive origin into the bearing.
                name: "StepDown",
                guard: Some(and_(eq(var("phase"), int(2)), gt(var("rem"), int(7)))),
                updates: vec![
                    Update {
                        var: "rem",
                        expr: sub(var("rem"), int(8)),
                    },
                    Update {
                        var: "bearing",
                        expr: add(var("bearing"), int(8)),
                    },
                ],
            },
            Action {
                // Move one whole px of negative origin into the bearing
                // (floor, NOT truncation: -0.5px becomes bearing -1 + phase 0.5).
                name: "StepUp",
                guard: Some(and_(eq(var("phase"), int(2)), gt(int(0), var("rem")))),
                updates: vec![
                    Update {
                        var: "rem",
                        expr: add(var("rem"), int(8)),
                    },
                    Update {
                        var: "bearing",
                        expr: sub(var("bearing"), int(8)),
                    },
                ],
            },
            Action {
                // Publish the placement the raster/blit will use.
                name: "Report",
                guard: Some(and_(eq(var("phase"), int(2)), rem_in_unit())),
                updates: vec![
                    Update {
                        var: "bearing",
                        expr: report_bearing,
                    },
                    Update {
                        var: "rem",
                        expr: report_rem,
                    },
                    Update {
                        var: "phase",
                        expr: int(3),
                    },
                ],
            },
        ],
        invariants: vec![
            Invariant {
                // Exact reconstruction: integer bearing + retained phase is the
                // designed position at EVERY step after Latch (the pre-fix
                // round-and-pin loses up to half a px here).
                name: "Decompose",
                expr: or_(
                    le(var("phase"), int(1)),
                    eq(add(var("bearing"), var("rem")), var("b")),
                ),
            },
            Invariant {
                // The reported sub-px phase is in [0, 1) — scaled: rem in [0, 8).
                name: "PhaseInUnit",
                expr: or_(neq(var("phase"), int(3)), rem_in_unit()),
            },
        ],
    }
}

/// W4 CURSOR-CUT-OUT CLIP — the abstract twin of the block-cursor cut-out's
/// x-clip window (the real code seam is `aterm_render::clip_span`, which every
/// cut-out blit routes through, and `glyph_quad`'s x-clip on the GPU; Tier-1
/// lives in `aterm-render/tests/cursor_ink.rs`, whose exhaustive lattice tests
/// check the SAME partition/no-bleed law on the shipping fns and whose pixel
/// sweep enforces it end-to-end: the complement of the cursor rect is
/// byte-identical to the no-cursor frame).
///
/// The sin (audit sin 3): the cut-out re-blitted the ENTIRE glyph in cell-bg
/// with no horizontal clip, so a cursor on the '>' of a '=>' ligature painted
/// bg over the arrow's lead-cell ink, and on a wide CJK lead the full-glyph
/// re-blit erased the ideograph's right half. The fix clips every cut-out
/// paint to the cursor rect's x-span `[w0, w1)`: the visible cut-out slice is
/// the INTERSECTION `[max(g0, w0), min(g0+gw, w1))` of the glyph extent with
/// the window.
///
/// After the nondeterministic picks (`PickGlyph` → `PickWinLo` → `PickWinHi`,
/// every extent × window on the bounded lattice), `Slice` computes the
/// intersection with `min`/`max` as `if/else` (ty's Expr has no min/max
/// builtins). The left/right remainders `[g0, m0)` / `[m1, g0+gw)` tile the
/// extent around the middle BY CONSTRUCTION (the three lengths telescope to
/// `gw`), so the safety content is the two non-trivial laws: `SlicesOrdered`
/// — `g0 <= m0 <= m1 <= g0+gw`, the clamp keeps every slice inside the glyph
/// — and `CutoutInsideWindow` — a non-empty cut-out slice never exits the
/// window (NO-BLEED: nothing outside the cursor rect is ever repainted).
/// `Buggy = 1` gates the PRE-FIX slice into `Slice` (the whole glyph extent,
/// unclipped): any window that strictly clips then violates
/// `CutoutInsideWindow`, so `ty` PROVES the clip law at `Buggy=0` and CATCHES
/// the shipped bleed at `Buggy=1` (counterexample).
// Skip (T2 vcgen-budget lane): a spec-model DATA constructor — nested
// `vec!`/struct literals whose aggregate-operand count exceeds the
// VC-generation work budget, so its obligations are left Unknown
// fail-closed regardless. No runtime logic and no panic surface beyond
// the idiomatic allocs; the MODEL it returns is what `ty` machine-checks.
#[cfg_attr(trust_verify, trust::skip)]
pub fn cursor_cutout_clip_model() -> Model {
    let min = |a: Expr, b: Expr| if_(le(a.clone(), b.clone()), a, b);
    let max = |a: Expr, b: Expr| if_(le(a.clone(), b.clone()), b, a);
    let end = || add(var("g0"), var("gw"));
    // Committed slice: clamp the window edge into the glyph extent. Buggy:
    // the unclipped pre-fix cut-out (the whole extent, window ignored).
    let clamped = |edge: &'static str| max(var("g0"), min(var(edge), end()));
    let buggy = || gt(cst("Buggy"), int(0));
    let settled_implies = |body: Expr| or_(neq(var("phase"), int(4)), body);
    Model {
        name: "CursorCutoutClip",
        consts: vec![("Buggy", 0)],
        vars: vec![
            StateVar {
                name: "phase",
                init: 0,
            },
            StateVar {
                name: "g0",
                init: 0,
            },
            StateVar {
                name: "gw",
                init: 0,
            },
            StateVar {
                name: "w0",
                init: 0,
            },
            StateVar {
                name: "w1",
                init: 0,
            },
            StateVar {
                name: "m0",
                init: 0,
            },
            StateVar {
                name: "m1",
                init: 0,
            },
        ],
        fn_vars: vec![],
        actions: vec![
            Action {
                // Every glyph extent on the lattice: origin AND width range over
                // enough values that windows can hit the interior, an edge, or miss.
                name: "PickGlyph",
                guard: Some(eq(var("phase"), int(0))),
                updates: vec![
                    Update {
                        var: "g0",
                        expr: in_range(int(0), int(3)),
                    },
                    Update {
                        var: "gw",
                        expr: in_range(int(0), int(4)),
                    },
                    Update {
                        var: "phase",
                        expr: int(1),
                    },
                ],
            },
            Action {
                name: "PickWinLo",
                guard: Some(eq(var("phase"), int(1))),
                updates: vec![
                    Update {
                        var: "w0",
                        expr: in_range(int(0), int(6)),
                    },
                    Update {
                        var: "phase",
                        expr: int(2),
                    },
                ],
            },
            Action {
                // w1 >= w0: a well-formed [w0, w1) window (the callers pass
                // x0 .. x0 + cur_w with cur_w >= 0).
                name: "PickWinHi",
                guard: Some(eq(var("phase"), int(2))),
                updates: vec![
                    Update {
                        var: "w1",
                        expr: in_range(var("w0"), int(6)),
                    },
                    Update {
                        var: "phase",
                        expr: int(3),
                    },
                ],
            },
            Action {
                // The clip: middle slice = extent ∩ window (committed), or the
                // whole unclipped extent (Buggy — the pre-W4 cut-out).
                name: "Slice",
                guard: Some(eq(var("phase"), int(3))),
                updates: vec![
                    Update {
                        var: "m0",
                        expr: if_(buggy(), var("g0"), clamped("w0")),
                    },
                    Update {
                        var: "m1",
                        expr: if_(buggy(), end(), clamped("w1")),
                    },
                    Update {
                        var: "phase",
                        expr: int(4),
                    },
                ],
            },
        ],
        invariants: vec![
            Invariant {
                // g0 <= m0 <= m1 <= g0+gw: the slice stays inside the glyph, so
                // the left/right remainders [g0,m0) / [m1,g0+gw) tile around it.
                name: "SlicesOrdered",
                expr: settled_implies(and_(
                    le(var("g0"), var("m0")),
                    and_(le(var("m0"), var("m1")), le(var("m1"), end())),
                )),
            },
            Invariant {
                // NO-BLEED: a non-empty cut-out slice never exits the window —
                // nothing outside the cursor rect is ever repainted.
                name: "CutoutInsideWindow",
                expr: settled_implies(or_(
                    le(var("m1"), var("m0")),
                    and_(le(var("w0"), var("m0")), le(var("m1"), var("w1"))),
                )),
            },
        ],
    }
}

/// SPAWN-TIME LOCALE GUARANTEE — the child process aterm launches must run under a
/// UTF-8 `LC_CTYPE` whatever locale aterm inherited. `LC_CTYPE` is the POSIX
/// character-encoding category; under a non-UTF-8 one, locale-aware programs (emacs,
/// vim, python) re-encode multibyte terminal output to the ASCII codeset and emit a
/// literal `?` per character — the box-drawing-`?` bug. The real decision is
/// `aterm_pty::resolve_spawn_locale` (POSIX precedence `LC_ALL > LC_CTYPE > LANG`,
/// empty == unset); this is its abstract twin, with the real-code binding in
/// aterm-pty's `spawn_locale_conformance_*` test.
///
/// Scalar projection `<<present, eff_utf8, ctype, resolved>>`: `present` = any locale
/// var is set non-empty; `eff_utf8` = the effective inherited encoding is already
/// UTF-8; `ctype` = the child's resulting `LC_CTYPE` (1 = UTF-8) once `resolved`. The
/// two `Observe*` actions spread the nondeterministic input shape — nothing set; a
/// non-UTF-8 locale present; a UTF-8 locale present — and `Resolve` runs the fix once.
///
/// `Buggy` gates the SHIPPED defect: with `Buggy = 0` (committed) `Resolve` always
/// yields `ctype = 1`; with `Buggy = 1` it forces UTF-8 ONLY when nothing is present
/// (the old all-unset guard), so a present-but-non-UTF-8 locale leaves `ctype = 0`
/// and `ChildHasUtf8Ctype` is violated. Thus `ty` PROVES the guarantee (Buggy=0) and
/// CATCHES the real regression (Buggy=1 → counterexample). Exercises a nested `if`,
/// a constant-guarded update, and disjunction.
// Skip (T2 vcgen-budget lane): a spec-model DATA constructor — nested
// `vec!`/struct literals whose aggregate-operand count exceeds the
// VC-generation work budget, so its obligations are left Unknown
// fail-closed regardless. No runtime logic and no panic surface beyond
// the idiomatic allocs; the MODEL it returns is what `ty` machine-checks.
#[cfg_attr(trust_verify, trust::skip)]
pub fn spawn_locale_model() -> Model {
    Model {
        name: "SpawnLocale",
        consts: vec![("Buggy", 0)],
        vars: vec![
            StateVar {
                name: "present",
                init: 0,
            },
            StateVar {
                name: "eff_utf8",
                init: 0,
            },
            StateVar {
                name: "ctype",
                init: 0,
            },
            StateVar {
                name: "resolved",
                init: 0,
            },
        ],
        fn_vars: vec![],
        actions: vec![
            Action {
                name: "ObserveNonUtf8", // a non-UTF-8 locale is present (e.g. LANG=C)
                guard: Some(and_(
                    eq(var("resolved"), int(0)),
                    eq(var("present"), int(0)),
                )),
                updates: vec![Update {
                    var: "present",
                    expr: int(1),
                }], // eff_utf8 stays 0
            },
            Action {
                name: "ObserveUtf8", // a UTF-8 locale is present
                guard: Some(and_(
                    eq(var("resolved"), int(0)),
                    eq(var("present"), int(0)),
                )),
                updates: vec![
                    Update {
                        var: "present",
                        expr: int(1),
                    },
                    Update {
                        var: "eff_utf8",
                        expr: int(1),
                    },
                ],
            },
            Action {
                name: "Resolve", // run resolve_spawn_locale once; sets the child's LC_CTYPE
                guard: Some(eq(var("resolved"), int(0))),
                updates: vec![
                    Update {
                        var: "resolved",
                        expr: int(1),
                    },
                    // Buggy=1: IF present=0 THEN 1 ELSE eff_utf8 (old all-unset guard
                    // leaves a present non-UTF-8 locale unfixed). Buggy=0: always 1.
                    Update {
                        var: "ctype",
                        expr: if_(
                            eq(cst("Buggy"), int(1)),
                            if_(eq(var("present"), int(0)), int(1), var("eff_utf8")),
                            int(1),
                        ),
                    },
                ],
            },
        ],
        invariants: vec![Invariant {
            name: "ChildHasUtf8Ctype",
            // resolved => ctype = 1
            expr: or_(eq(var("resolved"), int(0)), eq(var("ctype"), int(1))),
        }],
    }
}

/// A fifth derived model — TRANSACTION ATOMICITY / no-lost-update under
/// optimistic concurrency (the `Transact` kernel-family property). A transaction
/// reads the head at `tbase` (`Begin`); concurrent `Write`s may advance `seq`. At
/// commit, the correct discipline is: commit only if no write intervened
/// (`seq = tbase`), otherwise ABORT — committing against a stale `tbase` would
/// clobber the concurrent write (a lost update). Scalar projection over
/// `<<seq, tbase, active, lost>>`, edits-per-txn `K`.
///
/// `Buggy` gates the bad path: with `Buggy = 0` (committed) a conflict can only
/// `Abort`, so `lost` stays 0; with `Buggy = 1` the txn may commit despite a
/// conflict (`seq' = tbase + K`, overwriting the intervening write) and sets
/// `lost = 1`. So `ty` proves `NoLostUpdate` (Buggy=0) and catches it (Buggy=1).
/// Exercises the `Expr` conjunction (`/\`) operator in guards.
// Skip (T2 vcgen-budget lane): a spec-model DATA constructor — nested
// `vec!`/struct literals whose aggregate-operand count exceeds the
// VC-generation work budget, so its obligations are left Unknown
// fail-closed regardless. No runtime logic and no panic surface beyond
// the idiomatic allocs; the MODEL it returns is what `ty` machine-checks.
#[cfg_attr(trust_verify, trust::skip)]
pub fn transact_model() -> Model {
    Model {
        name: "Transact",
        consts: vec![("MaxSeq", 4), ("K", 2), ("Buggy", 0)],
        vars: vec![
            StateVar {
                name: "seq",
                init: 0,
            },
            StateVar {
                name: "tbase",
                init: 0,
            },
            StateVar {
                name: "active",
                init: 0,
            },
            StateVar {
                name: "lost",
                init: 0,
            },
        ],
        fn_vars: vec![],
        actions: vec![
            Action {
                name: "Write", // a concurrent writer advances the committed head
                guard: Some(le(var("seq"), sub(cst("MaxSeq"), int(1)))),
                updates: vec![Update {
                    var: "seq",
                    expr: add(var("seq"), int(1)),
                }],
            },
            Action {
                name: "Begin", // a txn reads the current head as its base version
                guard: Some(eq(var("active"), int(0))),
                updates: vec![
                    Update {
                        var: "active",
                        expr: int(1),
                    },
                    Update {
                        var: "tbase",
                        expr: var("seq"),
                    },
                ],
            },
            Action {
                name: "CommitClean", // no write intervened: commit K edits atomically
                guard: Some(and_(
                    and_(eq(var("active"), int(1)), eq(var("seq"), var("tbase"))),
                    le(var("seq"), sub(cst("MaxSeq"), cst("K"))),
                )),
                updates: vec![
                    Update {
                        var: "seq",
                        expr: add(var("seq"), cst("K")),
                    },
                    Update {
                        var: "active",
                        expr: int(0),
                    },
                ],
            },
            Action {
                name: "Abort", // a write intervened (seq > tbase): correct path aborts
                guard: Some(and_(
                    eq(var("active"), int(1)),
                    gt(var("seq"), var("tbase")),
                )),
                updates: vec![Update {
                    var: "active",
                    expr: int(0),
                }],
            },
            Action {
                name: "BuggyCommit", // conflict committed anyway -> clobbers, lost update
                guard: Some(and_(
                    and_(
                        and_(eq(var("active"), int(1)), gt(var("seq"), var("tbase"))),
                        eq(cst("Buggy"), int(1)),
                    ),
                    le(var("tbase"), sub(cst("MaxSeq"), cst("K"))),
                )),
                updates: vec![
                    Update {
                        var: "seq",
                        expr: add(var("tbase"), cst("K")),
                    },
                    Update {
                        var: "active",
                        expr: int(0),
                    },
                    Update {
                        var: "lost",
                        expr: int(1),
                    },
                ],
            },
        ],
        invariants: vec![Invariant {
            name: "NoLostUpdate",
            expr: eq(var("lost"), int(0)), // lost = 0
        }],
    }
}

/// A fifth derived model — the event-log SPINE: gap-free, monotone, `seq == count`
/// (the `Kernel` family property). Each `Append` assigns the next contiguous seq
/// and bumps the count, so the head seq always equals the number of events — no
/// gaps, no duplicates. `Buggy` makes an append jump seq by 2 (a gap), so
/// `seq != count` and `SeqIsCount` is violated. ty proves it (Buggy=0) and catches
/// the gap (Buggy=1).
// Skip (T2 vcgen-budget lane): a spec-model DATA constructor — nested
// `vec!`/struct literals whose aggregate-operand count exceeds the
// VC-generation work budget, so its obligations are left Unknown
// fail-closed regardless. No runtime logic and no panic surface beyond
// the idiomatic allocs; the MODEL it returns is what `ty` machine-checks.
#[cfg_attr(trust_verify, trust::skip)]
pub fn kernel_model() -> Model {
    Model {
        name: "Kernel",
        consts: vec![("MaxSeq", 5), ("Buggy", 0)],
        vars: vec![
            StateVar {
                name: "seq",
                init: 0,
            },
            StateVar {
                name: "count",
                init: 0,
            },
        ],
        // Action `Emit` (not `Append`, which clashes with ty's Sequences builtin in
        // a single-action spec — see the ring's `Push`).
        fn_vars: vec![],
        actions: vec![Action {
            name: "Emit",
            guard: Some(le(var("seq"), sub(cst("MaxSeq"), int(1)))),
            updates: vec![
                Update {
                    var: "count",
                    expr: add(var("count"), int(1)),
                },
                // seq' = IF Buggy = 1 THEN seq + 2 ELSE seq + 1   (Buggy opens a gap)
                Update {
                    var: "seq",
                    expr: if_(
                        eq(cst("Buggy"), int(1)),
                        add(var("seq"), int(2)),
                        add(var("seq"), int(1)),
                    ),
                },
            ],
        }],
        invariants: vec![Invariant {
            name: "SeqIsCount",
            expr: eq(var("seq"), var("count")), // seq = count (gap-free, monotone spine)
        }],
    }
}

/// PROOF-CARRYING DYNAMIC SOFTWARE UPDATE — the QUIESCENCE-SAFETY obligation, Rung 0
/// of `docs/RFC-proof-carrying-dsu.md`.
///
/// The crux of applying an update to a RUNNING process (rather than at the next cold
/// launch): a live in-flight computation was begun under the OLD version's memory
/// layout; resuming it under the NEW version tears state. So an update may be applied
/// ONLY at a QUIESCENCE point — no request in flight. This model proves that a
/// quiescence-GATED apply never tears, and that dropping the gate (the `Buggy` mutant
/// = apply-mid-flight) is caught by the checker — so the safety precondition Trust
/// must discharge for any real DSU is itself formally pinned, not asserted in prose.
///
/// Scalar projection over `<<inflight, applied, torn, served>>`:
/// * `Begin`  — a request starts under the current version (`inflight := 1`), bounded
///   by `served <= MaxReq - 1`.
/// * `Finish` — the request completes cleanly (`inflight := 0`, `served += 1`).
/// * `ApplyQuiescent` — apply the update at a quiescence point (`applied = 0 /\
///   inflight = 0`): the transformer runs on SETTLED state, so nothing tears.
/// * `BuggyApplyInflight` — (`Buggy = 1`) apply while a request is in flight: the
///   in-flight computation, begun under the old layout, is now under new code → a
///   TEAR (`torn := 1`).
///
/// What is proven (the `Buggy`-convention shape shared with `transact_model` etc.):
/// `torn` is set ONLY by the mid-flight apply, so `NoTear` (`torn = 0`) holds over the
/// whole state space at `Buggy = 0` because the quiescence-gated `ApplyQuiescent` never
/// reaches an in-flight state — and `assert_proves_and_catches` REQUIRES a
/// counterexample at `Buggy = 1`, where the reachable `BuggyApplyInflight` tears state.
/// So the model proves the safety property that the mid-flight apply is FORBIDDEN (a
/// reachable defect the checker catches), not a liveness claim that requests complete.
// Skip (T2 vcgen-budget lane): a spec-model DATA constructor — nested
// `vec!`/struct literals whose aggregate-operand count exceeds the
// VC-generation work budget, so its obligations are left Unknown
// fail-closed regardless. No runtime logic and no panic surface beyond
// the idiomatic allocs; the MODEL it returns is what `ty` machine-checks.
#[cfg_attr(trust_verify, trust::skip)]
pub fn dsu_quiescence_model() -> Model {
    Model {
        name: "DsuQuiescence",
        consts: vec![("MaxReq", 3), ("Buggy", 0)],
        vars: vec![
            StateVar {
                name: "inflight", // a request is mid-processing under the current version
                init: 0,
            },
            StateVar {
                name: "applied", // the dynamic update has been applied
                init: 0,
            },
            StateVar {
                name: "torn", // SAFETY violation: an in-flight computation survived an apply
                init: 0,
            },
            StateVar {
                name: "served", // completed request cycles (bounds the state space)
                init: 0,
            },
        ],
        fn_vars: vec![],
        actions: vec![
            Action {
                name: "Begin", // start a request under the current version
                guard: Some(and_(
                    eq(var("inflight"), int(0)),
                    le(var("served"), sub(cst("MaxReq"), int(1))),
                )),
                updates: vec![Update {
                    var: "inflight",
                    expr: int(1),
                }],
            },
            Action {
                name: "Finish", // the request completes cleanly
                guard: Some(eq(var("inflight"), int(1))),
                updates: vec![
                    Update {
                        var: "inflight",
                        expr: int(0),
                    },
                    Update {
                        var: "served",
                        expr: add(var("served"), int(1)),
                    },
                ],
            },
            Action {
                name: "ApplyQuiescent", // apply ONLY at quiescence (no request in flight)
                guard: Some(and_(
                    eq(var("applied"), int(0)),
                    eq(var("inflight"), int(0)),
                )),
                updates: vec![Update {
                    var: "applied",
                    expr: int(1),
                }],
            },
            Action {
                name: "BuggyApplyInflight", // apply mid-flight -> tears the in-flight request
                guard: Some(and_(
                    and_(eq(var("applied"), int(0)), eq(var("inflight"), int(1))),
                    eq(cst("Buggy"), int(1)),
                )),
                updates: vec![
                    Update {
                        var: "applied",
                        expr: int(1),
                    },
                    Update {
                        var: "torn",
                        expr: int(1),
                    },
                ],
            },
        ],
        invariants: vec![Invariant {
            name: "NoTear",
            expr: eq(var("torn"), int(0)), // torn = 0
        }],
    }
}

/// PROOF-CARRYING DSU — the SNAPSHOT ROUND-TRIP obligation, Rung 1a of
/// `docs/RFC-proof-carrying-dsu.md`.
///
/// Strategy A (seamless re-exec) hands the session set to the new binary as a
/// serialized manifest; the new process must restore EXACTLY that set — no session
/// lost, none fabricated — or the update silently drops (or duplicates) a tab. This
/// models the round-trip `restore ∘ pack` as an identity on the session count:
/// `Pack` adds a session to the manifest; `Restore` faithfully re-materializes one;
/// the `Buggy` mutant (a transformer that drops a session across the handoff) sets
/// `lost`. `ty` checks the SAFETY invariant `NoLossNoFabricate` (`lost = 0 /\ restored
/// <= packed`): the no-fabricate half (`restored <= packed`) is a genuine non-vacuous
/// bound, and `lost = 0` holds at Buggy=0 because only `BuggyDrop` sets it — so, in the
/// repo's `Buggy`-convention, the model proves a session-dropping TRANSITION is
/// FORBIDDEN (caught at Buggy=1), not the liveness completion `restored == packed`. The
/// concrete no-loss round-trip is the REAL serde identity check
/// (`session_handoff_roundtrips_the_whole_set`, `session_store.rs`), which is what pins
/// the shipping serializer.
// Skip (T2 vcgen-budget lane): a spec-model DATA constructor — nested
// `vec!`/struct literals whose aggregate-operand count exceeds the
// VC-generation work budget, so its obligations are left Unknown
// fail-closed regardless. No runtime logic and no panic surface beyond
// the idiomatic allocs; the MODEL it returns is what `ty` machine-checks.
#[cfg_attr(trust_verify, trust::skip)]
pub fn handoff_roundtrip_model() -> Model {
    Model {
        name: "HandoffRoundTrip",
        consts: vec![("N", 3), ("Buggy", 0)],
        vars: vec![
            StateVar {
                name: "packed", // sessions written into the handoff manifest
                init: 0,
            },
            StateVar {
                name: "restored", // sessions re-materialized by the new process
                init: 0,
            },
            StateVar {
                name: "lost", // SAFETY violation: a session dropped across the round-trip
                init: 0,
            },
        ],
        fn_vars: vec![],
        actions: vec![
            Action {
                name: "Pack", // serialize one more session into the manifest
                guard: Some(le(var("packed"), sub(cst("N"), int(1)))),
                updates: vec![Update {
                    var: "packed",
                    expr: add(var("packed"), int(1)),
                }],
            },
            Action {
                name: "Restore", // the new process faithfully restores a packed session
                guard: Some(gt(var("packed"), var("restored"))),
                updates: vec![Update {
                    var: "restored",
                    expr: add(var("restored"), int(1)),
                }],
            },
            Action {
                name: "BuggyDrop", // a lossy transformer drops a session across the handoff
                guard: Some(and_(
                    eq(cst("Buggy"), int(1)),
                    gt(var("packed"), var("restored")),
                )),
                updates: vec![Update {
                    var: "lost",
                    expr: int(1),
                }],
            },
        ],
        invariants: vec![Invariant {
            name: "NoLossNoFabricate",
            // lost = 0 /\ restored <= packed  (never drop a session, never invent one)
            expr: and_(eq(var("lost"), int(0)), le(var("restored"), var("packed"))),
        }],
    }
}

/// PROOF-CARRYING DSU — the FD-HANDOFF NO-LEAK obligation, Rung 1b of
/// `docs/RFC-proof-carrying-dsu.md`.
///
/// The seamless re-exec clears `FD_CLOEXEC` on each live PTY master so it SURVIVES the
/// exec (proven with real syscalls in `aterm-pty`'s
/// `cloexec_controls_master_survival_across_exec`). But a master whose CLOEXEC was
/// cleared and that is then NEITHER re-adopted NOR closed is a LEAK — a live, ungated
/// PTY channel dangling across the exec, defeating the cross-session isolation the
/// CLOEXEC default enforces. This models the incoming side's accounting: `adopted +
/// closed <= prepared` always (never over-account), and `leaked` is set ONLY by the
/// `BuggyDrop` mutant (adopt fails and the fd is dropped WITHOUT closing).
