                failed = if (
                    present_succeeded == 0 && Buggy == 0 && attempts == AttemptLimit
                ) { 1 } else { 0 };
                stale_capture = if (
                    present_succeeded == 0 && Buggy == 1
                ) { 1 } else { stale_capture };
                staged = if present_succeeded == 1 { 0 } else { staged };
